using System.Diagnostics;
using System.Globalization;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Threading.Channels;
namespace MRS;
internal sealed record MeshOptions(string Protocol,long Frequency,int Sf=11,int Bandwidth=250000,int CodingRate=1,int Sync=43,bool PublicText=true);
internal sealed class MeshRadio:IDisposable
{
 private sealed class Session(IqFrame first,PacketContext context,MeshOptions options){internal readonly IqFrame First=first;internal readonly PacketContext Context=context;internal readonly MeshOptions Options=options;internal readonly Channel<byte[]> Input=Channel.CreateBounded<byte[]>(128);internal readonly CancellationTokenSource Cancel=new();internal Task Work=Task.CompletedTask;internal bool Failed;}
 private readonly object gate=new();private Session? active;private MeshOptions? options;private bool disposed;private string state="Off";private long packets,drops;private readonly Queue<PacketObservation> output=[];
 internal string Status{get{lock(gate)return state+$" · frames {packets} · dropped {drops}";}}
 internal void Start(MeshOptions value){if(value.Sf is <7 or >12||value.Bandwidth is not (62500 or 125000 or 250000 or 500000)||value.CodingRate is <1 or >4||value.Sync is <0 or >255||value.Frequency<1||value.Frequency>6000000000)throw new IOException("Select SF7–12, supported bandwidth, CR 4/5–4/8, sync 0–255 and a valid RF frequency.");lock(gate){ResetCore();options=value;state="Waiting for live SDR / I/Q replay";}}
 internal void Stop(){lock(gate){options=null;ResetCore();state="Off";}}internal void Reset(){lock(gate){ResetCore();state=options!=null?"Source changed — waiting for fresh capture":"Off";}}internal void Complete(){lock(gate)active?.Input.Writer.TryComplete();}
 private void ResetCore(){active?.Cancel.Cancel();active?.Input.Writer.TryComplete();active=null;}
 internal void Feed(IqFrame frame,PacketContext context){lock(gate){if(disposed||options==null)return;var o=options;double usable=frame.UsableBandwidthHz??frame.Rate;if(frame.Rate<o.Bandwidth*2||Math.Abs(o.Frequency-frame.Frequency)+o.Bandwidth*.6>usable/2){state="LoRa channel does not fit usable I/Q — tune capture closer / increase sample rate";return;}if(active==null||active.Context.Key!=context.Key||active.First.Rate!=frame.Rate||active.First.Frequency!=frame.Frequency||active.First.Format!=frame.Format){ResetCore();var s=new Session(frame with{Data=[]},context with{FrequencyHz=o.Frequency},o);active=s;s.Work=Task.Run(()=>Run(s));}if(active.Failed)return;if(!active.Input.Writer.TryWrite((byte[])frame.Data.Clone())){drops++;ResetCore();state="LoRa overrun — reacquiring";}}}
 private static Process Worker(string path,IEnumerable<string> args){if(!File.Exists(path))throw new FileNotFoundException("Missing decoder helper; extract full release ZIP",path);var p=new Process{StartInfo=new(path){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true,WorkingDirectory=Path.GetDirectoryName(path)!}};foreach(var a in args)p.StartInfo.ArgumentList.Add(a);return p;}
 private async Task Run(Session s){Process? bridge=null,decoder=null;try{var o=s.Options;int factor=Math.Clamp(s.First.Rate/(o.Bandwidth*2),1,128);double rate=s.First.Rate/(double)factor;if(rate/(o.Bandwidth*2)>2)throw new IOException("Capture rate too high for this LoRa bandwidth; use a lower sample rate");string root=Path.Combine(AppContext.BaseDirectory,"Decoders");bridge=Worker(Path.Combine(root,"Sensors","mrs-iq-channel.exe"),new[]{s.First.Rate.ToString(),factor.ToString(),(o.Frequency-s.First.Frequency).ToString(),s.First.Format==IqSampleFormat.Signed8?"1":"0","0"});decoder=Worker(Path.Combine(root,"RadioData","mrs-lora.exe"),new[]{o.Sf.ToString(),o.Bandwidth.ToString(),o.CodingRate.ToString(),o.Sync.ToString(),o.Frequency.ToString(),rate.ToString(CultureInfo.InvariantCulture)});bridge.Start();decoder.Start();using var kill=s.Cancel.Token.Register(()=>{foreach(var p in new[]{bridge,decoder})try{p.Kill(true);}catch{}});string error="";var e1=SensorPipeline.Lines(bridge.StandardError,l=>error=l,s.Cancel.Token);var e2=SensorPipeline.Lines(decoder.StandardError,l=>error=l,s.Cancel.Token);var pipe=Task.Run(async()=>{await bridge.StandardOutput.BaseStream.CopyToAsync(decoder.StandardInput.BaseStream,s.Cancel.Token);decoder.StandardInput.Close();});var read=SensorPipeline.Lines(decoder.StandardOutput,l=>{lock(gate){if(active!=s)return;try{var row=MeshPacket.Parse(l,s.Context,o);if(row!=null){if(output.Count>=500)output.Dequeue();output.Enqueue(row);packets++;}}catch(JsonException){}catch(FormatException){}}},s.Cancel.Token);lock(gate)if(active==s)state=$"Receiving {o.Protocol} · SF{o.Sf} / {o.Bandwidth/1000.0:0.###} kHz / CR4/{o.CodingRate+4}";await foreach(var b in s.Input.Reader.ReadAllAsync(s.Cancel.Token)){await bridge.StandardInput.BaseStream.WriteAsync(b,s.Cancel.Token);await bridge.StandardInput.BaseStream.FlushAsync(s.Cancel.Token);}bridge.StandardInput.Close();await bridge.WaitForExitAsync(s.Cancel.Token);await pipe;await decoder.WaitForExitAsync(s.Cancel.Token);await Task.WhenAll(read,e1,e2);if(bridge.ExitCode!=0||decoder.ExitCode!=0)throw new IOException(error.Length>0?error:"LoRa worker failed");}catch(OperationCanceledException){}catch(Exception ex){lock(gate){s.Failed=true;s.Input.Writer.TryComplete();if(active==s)state="LoRa stopped: "+ex.Message;}}finally{foreach(var p in new[]{bridge,decoder}){try{if(p is {HasExited:false})p.Kill(true);}catch{}p?.Dispose();}}}
 internal PacketObservation[] Drain(){lock(gate){var a=output.ToArray();output.Clear();return a;}}public void Dispose(){lock(gate){disposed=true;ResetCore();}}
}
internal static class MeshPacket
{
 private static readonly byte[] MeshtasticPublic=Convert.FromHexString("D4F1BBCF01F6A5E78A50E27B22E7D56B"),MeshCorePublic=Convert.FromBase64String("izOH6cXN6mrJ5e26oRXNcg==");
 private static uint U32(ReadOnlySpan<byte>b,int at)=>System.Buffers.Binary.BinaryPrimitives.ReadUInt32LittleEndian(b.Slice(at,4));
 internal static PacketObservation? Parse(string line,PacketContext c,MeshOptions o){using var d=JsonDocument.Parse(line);var j=d.RootElement;int status=j.GetProperty("status").GetInt32();bool crc=j.GetProperty("has_crc").GetBoolean()&&j.GetProperty("crc_ok").GetBoolean();byte[] raw=Convert.FromHexString(j.GetProperty("hex").GetString()??"");string kind=status==0?"LoRa header only":status==1?"LoRa CRC failed":"LoRa payload",text=$"SF{o.Sf} · BW {o.Bandwidth/1000.0:0.###} kHz · SNR {j.GetProperty("snr_db")} dB · sync 0x{j.GetProperty("sync").GetInt32():X2} · {raw.Length} bytes",from="",to="";string validation=crc?"LoRa payload CRC passed":"Unverified LoRa detection";if(j.TryGetProperty("crc_method",out var method)&&method.GetInt32()>0)validation+=$" · recovered CRC method {method.GetInt32()}";bool matching=o.Sync==0||j.GetProperty("sync").GetInt32()==o.Sync;if(!matching)validation+=" · sync differs from selected profile";
  if(status==2&&crc&&matching){if(o.Protocol=="Meshtastic"&&raw.Length>=17){uint sender=U32(raw,4),id=U32(raw,8);from=$"!{sender:X8}";to=$"!{U32(raw,0):X8}";kind="Mesh envelope";text+=$" · packet {id:X8} · channel hash {raw[13]:X2} · remaining hops {raw[12]&7} · relay {raw[15]:X2} · encrypted payload";if(o.PublicText&&raw[13]==8){try{var plain=MeshtasticPlain(raw,MeshtasticPublic);if(Data(plain,out int port,out var payload)){kind=$"Port {port} (public-key candidate)";text+=" · "+Describe(port,payload);validation+=" · default public key, no payload authentication";}}catch(Exception e) when(e is CryptographicException or DecoderFallbackException or FormatException or OverflowException){}}}
   else if(o.Protocol=="MeshCore"&&Core(raw,out int type,out byte[] payload,out string path)){kind="MeshCore "+type; text+=" · "+path;if(type==4&&payload.Length>=101){from=Convert.ToHexString(payload.AsSpan(0,32));int flags=payload[100],at=101;text+=$" · advertised node type {flags&15}";if((flags&16)!=0&&payload.Length>=at+8){double lat=(int)U32(payload,at)/1e6,lon=(int)U32(payload,at+4)/1e6;at+=8;if(Math.Abs(lat)<=90&&Math.Abs(lon)<=180)text+=$" · position {lat:F6}, {lon:F6}";}if((flags&32)!=0)at+=2;if((flags&64)!=0)at+=2;if((flags&128)!=0&&at<payload.Length)text+=" · name "+Encoding.UTF8.GetString(payload,at,Math.Min(32,payload.Length-at));validation+=" · advert signature not verified";}
    else if(type==5&&o.PublicText&&PublicCore(payload) is {} msg){text+=" · Public: "+msg;validation+=" · public-channel 16-bit HMAC matched";}else text+=" · opaque / encrypted payload";}
  }
  return new(DateTimeOffset.UtcNow,c.Source,c.Replay,o.Frequency,c.Replay&&c.PositionSeconds is double start&&j.TryGetProperty("sample_index",out var sample)?start+sample.GetInt64()/(2.0*o.Bandwidth):c.PositionSeconds,validation,from,to,"",kind,text,null,Convert.ToHexString(raw),o.Protocol,crc&&matching,SourceKey:c.Key,DecoderJson:line);
 }
 internal static byte[] MeshtasticPlain(byte[] raw,byte[] key){byte[] counter=new byte[16];raw.AsSpan(8,4).CopyTo(counter);raw.AsSpan(4,4).CopyTo(counter.AsSpan(8));using var aes=Aes.Create();aes.Key=key;aes.Mode=CipherMode.ECB;aes.Padding=PaddingMode.None;using var enc=aes.CreateEncryptor();byte[] output=new byte[raw.Length-16];for(int at=0;at<output.Length;at+=16){byte[] pad=enc.TransformFinalBlock(counter,0,16);for(int i=0;i<16&&at+i<output.Length;i++)output[at+i]=(byte)(raw[16+at+i]^pad[i]);for(int k=15;k>=0;k--)if(++counter[k]!=0)break;}return output;}
 private static ulong Var(byte[]b,ref int at){ulong v=0;for(int n=0;n<10;n++){if(at>=b.Length)throw new FormatException();byte x=b[at++];v|=(ulong)(x&127)<<(7*n);if((x&128)==0)return v;}throw new FormatException();}
 internal static bool Data(byte[] b,out int port,out byte[] payload){port=0;payload=[];try{int at=0;while(at<b.Length){ulong tag=Var(b,ref at);int field=(int)(tag>>3),wire=(int)(tag&7);if(field==0)return false;if(wire==0){ulong value=Var(b,ref at);if(field==1){if(value>int.MaxValue)return false;port=(int)value;}}else if(wire==2){ulong size=Var(b,ref at);if(size>(ulong)(b.Length-at))return false;if(field==2)payload=b.AsSpan(at,(int)size).ToArray();at+=(int)size;}else if(wire==5){at+=4;}else if(wire==1){at+=8;}else return false;if(at>b.Length)return false;}return port>0&&port<512&&payload.Length>0;}catch(FormatException){return false;}}
 private static string Describe(int port,byte[] payload){if(port==1)return "Text: "+new UTF8Encoding(false,true).GetString(payload);if(port==3)return "Position protobuf: "+Convert.ToHexString(payload);if(port==4)return "NodeInfo protobuf: "+Convert.ToHexString(payload);if(port==67)return "Telemetry protobuf: "+Convert.ToHexString(payload);return "payload "+Convert.ToHexString(payload);}
 internal static bool Core(byte[] b,out int type,out byte[] payload,out string path){type=0;payload=[];path="";if(b.Length<3||(b[0]>>6)!=0)return false;int route=b[0]&3;type=(b[0]>>2)&15;int at=1+(route is 0 or 3?4:0);if(at>=b.Length)return false;int len=b[at++],hash=(len>>6)+1,hops=len&63;if(hash>3||hops*hash>64||at+hops*hash>=b.Length)return false;path=$"route {route} · hops {hops} · path {Convert.ToHexString(b.AsSpan(at,hops*hash))}";payload=b.AsSpan(at+hops*hash).ToArray();return true;}
 private static string? PublicCore(byte[] b){if(b.Length<19||(b.Length-3)%16!=0||b[0]!=SHA256.HashData(MeshCorePublic)[0])return null;byte[] cipher=b[3..],mac=HMACSHA256.HashData(MeshCorePublic,cipher);if(b[1]!=mac[0]||b[2]!=mac[1])return null;using var aes=Aes.Create();aes.Key=MeshCorePublic;byte[] plain=aes.DecryptEcb(cipher,PaddingMode.None);if((plain[4]>>2)!=0)return null;int end=Array.IndexOf(plain,(byte)0,5);if(end<0)end=plain.Length;try{return new UTF8Encoding(false,true).GetString(plain,5,end-5);}catch(DecoderFallbackException){return null;}}
}
